@startuml

class User {
  + ID : int
  + name : string
  + email : string
  + dateOfBirth : date
}

class Account {
  + accountNumber : int
}

class BusinessAccount extends Account {
  + companyName : string
  + monthlyFee : float
}

class PersonalAccount extends Account {
}

class Page {
  + pageName : string
  + visits : int
}

class AdvertisementPage extends Page {
  + bounceRate : float
  + clickThroughRate : float
  + conversionRate : float
}

User "1" -- "0..1" Account

Account "1" -- "0..*" Page : manages

PersonalAccount "0..1" -- "0..*" Page : has privileges on

@enduml

